-- +goose Up
CREATE TABLE users (
    id         TEXT        PRIMARY KEY, -- hack club auth id
    slack_id   TEXT        UNIQUE,      -- not every account has slack linked
    name       TEXT        NOT NULL DEFAULT '',
    api_key    TEXT        NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- one per machine, id generated by the client. seq counts per install
CREATE TABLE installs (
    id           UUID        PRIMARY KEY,
    user_id      TEXT        NOT NULL REFERENCES users (id),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX installs_user ON installs (user_id);

-- raw and append-only, credited time is derived from these
CREATE TABLE events (
    install_id  UUID        NOT NULL REFERENCES installs (id),
    seq         BIGINT      NOT NULL,
    ts          TIMESTAMPTZ NOT NULL,
    kind        TEXT        NOT NULL,
    session_id  TEXT        NOT NULL,
    project_id  TEXT        NOT NULL,
    harness     TEXT        NOT NULL,
    source      TEXT        NOT NULL,
    data        JSONB       NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (install_id, seq)
);
CREATE INDEX events_install_ts ON events (install_id, ts);

-- folder name only, never the path
CREATE TABLE projects (
    install_id UUID        NOT NULL REFERENCES installs (id),
    project_id TEXT        NOT NULL,
    name       TEXT        NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (install_id, project_id)
);

-- +goose Down
DROP TABLE projects;
DROP TABLE events;
DROP TABLE installs;
DROP TABLE users;
